def is_samepatterns(colors, patterns):
    """
    Checks if the colors list follows the same pattern as the patterns list.

    :param colors: List of color strings.
    :param patterns: List of pattern strings.
    :return: True if colors follow the same pattern as patterns, False otherwise.
    """
    if len(colors) != len(patterns):
        return False

    mapping = {}
    for color, pattern in zip(colors, patterns):
        if color in mapping:
            if mapping[color] != pattern:
                return False
        else:
            mapping[color] = pattern

    return True
